// Web Push (RFC 8030 / 8291 aes128gcm / 8292 VAPID) using only WebCrypto — no libraries, no secrets to manage:
// the VAPID key pair is generated by the Worker on first use and kept in the kv table.
import { kvGet, kvSet } from './util.js';

const enc = new TextEncoder();
const b64u = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb64u = (s) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4)), (c) => c.charCodeAt(0));
const cat = (...parts) => { const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0)); let o = 0; for (const p of parts) { out.set(p, o); o += p.length; } return out; };
async function hmac(key, data) {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await crypto.subtle.sign('HMAC', k, data));
}

/** VAPID key pair: { pub: base64url raw P-256 point, jwk: private JWK }. */
export async function vapidKeys(db) {
  let k = await kvGet(db, 'vapid');
  if (k && k.pub && k.jwk) return k;
  const pair = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  k = { pub: b64u(await crypto.subtle.exportKey('raw', pair.publicKey)), jwk: await crypto.subtle.exportKey('jwk', pair.privateKey) };
  await kvSet(db, 'vapid', k);
  return k;
}

async function vapidAuth(keys, endpoint, sub) {
  const aud = new URL(endpoint).origin;
  const head = b64u(enc.encode(JSON.stringify({ typ: 'JWT', alg: 'ES256' })));
  const body = b64u(enc.encode(JSON.stringify({ aud, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub })));
  const key = await crypto.subtle.importKey('jwk', keys.jwk, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(head + '.' + body));
  return `vapid t=${head}.${body}.${b64u(sig)}, k=${keys.pub}`;
}

/** Encrypt one payload for one subscription (single aes128gcm record). */
export async function encryptPayload(p256dh, auth, text) {
  const uaPub = unb64u(p256dh), secret = unb64u(auth);
  const eph = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const asPub = new Uint8Array(await crypto.subtle.exportKey('raw', eph.publicKey));
  const uaKey = await crypto.subtle.importKey('raw', uaPub, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const shared = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: uaKey }, eph.privateKey, 256));
  const prkKey = await hmac(secret, shared);
  const ikm = (await hmac(prkKey, cat(enc.encode('WebPush: info\0'), uaPub, asPub, new Uint8Array([1])))).slice(0, 32);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const prk = await hmac(salt, ikm);
  const cek = (await hmac(prk, cat(enc.encode('Content-Encoding: aes128gcm\0'), new Uint8Array([1])))).slice(0, 16);
  const nonce = (await hmac(prk, cat(enc.encode('Content-Encoding: nonce\0'), new Uint8Array([1])))).slice(0, 12);
  const key = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce }, key, cat(enc.encode(text), new Uint8Array([2]))));
  const rs = new Uint8Array([0, 0, 16, 0]);                               // record size 4096
  return cat(salt, rs, new Uint8Array([asPub.length]), asPub, ct);
}

export async function addSub(db, s) {
  if (!s || !s.endpoint || !s.keys || !s.keys.p256dh || !s.keys.auth) throw new Error('bad subscription');
  const subs = ((await kvGet(db, 'push_subs')) || []).filter((x) => x.endpoint !== s.endpoint);
  subs.push({ endpoint: s.endpoint, p256dh: s.keys.p256dh, auth: s.keys.auth, at: Date.now() });
  await kvSet(db, 'push_subs', subs.slice(-10));
  return { ok: true, devices: subs.length };
}
export async function removeSub(db, endpoint) {
  const subs = ((await kvGet(db, 'push_subs')) || []).filter((x) => x.endpoint !== endpoint);
  await kvSet(db, 'push_subs', subs);
  return { ok: true, devices: subs.length };
}

/** Send { title, body, tag } to every subscribed phone. Dead subscriptions (404/410) are dropped. */
export async function pushAll(env, msg) {
  const db = env.DB;
  const subs = (await kvGet(db, 'push_subs')) || [];
  if (!subs.length) return { sent: 0, devices: 0 };
  const keys = await vapidKeys(db);
  const sub = env.PUSH_SUBJECT || 'https://solar-monitor.oigoldpro.workers.dev';
  const text = JSON.stringify(msg);
  const dead = [], results = [];
  for (const s of subs) {
    try {
      const r = await fetch(s.endpoint, {
        method: 'POST',
        headers: { Authorization: await vapidAuth(keys, s.endpoint, sub), 'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream', TTL: '86400', Urgency: 'high', Topic: msg.tag || 'solar' },
        body: await encryptPayload(s.p256dh, s.auth, text),
      });
      results.push(r.status);
      if (r.status === 404 || r.status === 410) dead.push(s.endpoint);
    } catch (e) { results.push(String(e.message || e)); }
  }
  if (dead.length) await kvSet(db, 'push_subs', subs.filter((s) => !dead.includes(s.endpoint)));
  return { sent: results.filter((x) => x >= 200 && x < 300).length, devices: subs.length, results };
}

const COOLDOWN_MS = 3 * 3600000;
const hhmm = (ts) => new Date(ts + 7 * 3600000).toISOString().slice(11, 16);

/**
 * Battery events from one counter step. prevSoc/newSoc are on the internal scale (10 = empty, 90 = full).
 *  • empty: the counter was just reset to empty because the battery touched 50 V
 *  • full: the app % just reached 100 %
 * Each kind is sent at most once per 3 h so a battery hovering at the edge doesn't spam.
 */
export function batteryEvent(prevSoc, st, v, ts, scale = { p0: 10, p1: 90 }) {
  if (prevSoc == null || !st || st.soc == null) return null;
  if (st.src === 'empty' && prevSoc > scale.p0 + 0.05) {
    return { kind: 'empty', title: '🪫 แบตหมดแล้ว', body: `แบตแตะ ${v != null ? v.toFixed(1) : '50'} V เวลา ${hhmm(ts)} · บ้านกำลังสลับไปใช้ไฟการไฟฟ้า`, tag: 'batt-empty' };
  }
  if (prevSoc < scale.p1 - 0.05 && st.soc >= scale.p1 - 0.05) {
    return { kind: 'full', title: '🔋 แบตเต็ม 100%', body: `ชาร์จเต็มเวลา ${hhmm(ts)}${v != null ? ' · ' + v.toFixed(1) + ' V' : ''}`, tag: 'batt-full' };
  }
  return null;
}

export async function notifyBattery(env, ev, ts) {
  if (!ev) return null;
  const last = (await kvGet(env.DB, 'push_last')) || {};
  if (last[ev.kind] && ts - last[ev.kind] < COOLDOWN_MS) return { skipped: 'cooldown' };
  last[ev.kind] = ts;
  await kvSet(env.DB, 'push_last', last);
  const { kind, ...msg } = ev;
  return pushAll(env, msg);
}

export const SW_JS = `
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
self.addEventListener('push', (e) => {
  let d = {}; try { d = e.data ? e.data.json() : {}; } catch (x) { d = { body: e.data ? e.data.text() : '' }; }
  e.waitUntil(self.registration.showNotification(d.title || 'โซลาร์บ้าน', { body: d.body || '', icon: '/icon.png', badge: '/icon.png', tag: d.tag || 'solar', renotify: true, data: { url: '/' } }));
});
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {
    for (const c of list) if ('focus' in c) return c.focus();
    return self.clients.openWindow('/');
  }));
});
`;
